prompt --application/shared_components/reports/report_queries/bill_payers_details
begin
wwv_flow_imp_shared.create_shared_query(
 p_id=>wwv_flow_imp.id(4314224316641388)
,p_name=>'Bill_Payers_details'
,p_query_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT        Booking_m_id, Client_name, Event_name, Venue_name, event_start_date,',
'              event_end_date,  (nvl(DUE, 0)) Booking_Due  , ((select   nvl(sum(amount), 0)  ',
'              from    receive  where    booking_m_id =a.booking_m_id))Installment, ',
'              (nvl(DUE, 0)  - (select   nvl(sum(amount), 0)  ',
'              from    receive  where    booking_m_id =a.booking_m_id)) Receiveable_Bill            ',
'FROM          BOOKING_LOV_VIEW a',
'where         to_char(EVENT_END_DATE, ''MM/DD/YYYY'') <= to_char(sysdate,  ''MM/DD/YYYY'') ',
'and           BOOKING_M_ID NOT IN ( SELECT     BOOKING_M_ID',
'                                   FROM            BILL  )  ',
'order by     BOOKING_M_ID'))
,p_report_layout_id=>wwv_flow_imp.id(4377801169086686)
,p_format=>'PDF'
,p_output_file_name=>'Bill_Payers_details'
,p_content_disposition=>'INLINE'
);
wwv_flow_imp_shared.create_shared_query_stmnt(
 p_id=>wwv_flow_imp.id(4378208967088099)
,p_shared_query_id=>wwv_flow_imp.id(4314224316641388)
,p_sql_statement=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT        Booking_m_id, Client_name, Event_name, Venue_name, event_start_date,',
'              event_end_date,  (nvl(DUE, 0)) Booking_Due  , ((select   nvl(sum(amount), 0)  ',
'              from    receive  where    booking_m_id =a.booking_m_id))Installment, ',
'              (nvl(DUE, 0)  - (select   nvl(sum(amount), 0)  ',
'              from    receive  where    booking_m_id =a.booking_m_id)) Receiveable_Bill            ',
'FROM          BOOKING_LOV_VIEW a',
'where         to_char(EVENT_END_DATE, ''MM/DD/YYYY'') <= to_char(sysdate,  ''MM/DD/YYYY'') ',
'and           BOOKING_M_ID NOT IN ( SELECT     BOOKING_M_ID',
'                                   FROM            BILL  )  ',
'order by     BOOKING_M_ID'))
);
end;
