wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(2885396746128121)
,p_plug_name=>'Event Booking Status'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(86612000967782608514)
,p_plug_display_sequence=>20
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'htp.p(''<style>',
'table',
'{',
' border:1px solid black ;',
' border-collapse:collapse ;',
' width: 100%;',
'}',
'th',
'{',
' border: 1px solid black;',
' background-color:#454545;',
' color: white;',
' font-size: 14px ;',
' padding: 3px ;',
'}',
'td',
'{',
' border:1px solid black ;',
' text-align:center ;',
' padding: 1px 3px ;',
'}',
'',
'}',
'.highlighted-row {',
'    color: black;',
'}',
'',
'',
'',
'',
'',
'</style>'') ;',
'-----------------column heading-----------------',
'htp.p(''<center> <table style = "width:100%">',
'<tr>',
' <th style = "width: 30px"> Booking ID</th>',
' <th style = "width: 250px">Event Name</th>',
' <th style = "width: 50px">Total Amount</th>',
' <th style="width:50px">Advance</th>',
' <th style="width:50px">Due</th>',
'       <th style = "width:50px">Last Receive</th>',
' <th style = "width:50px">Total Receive</th>',
'   <th style = "width:50px">Payable BIll</th>',
'  <th style = "width:50px">Bill Paid</th>',
'   <th style = "width:50px">Payment Statue</th>',
' </tr>'') ;',
'-----------Query----------------------------',
'FOR pool in (select  booking_m_id,  Event_Name,  Total_amount, Advance, due,Total_receive,bill_paid,payable_bill,last_receive_amount, ',
'                     case when  payable_bill = bill_paid then ''Paid'' else ''Due'' end as Payment_status ',
'             from        event_status_view',
'             where  booking_m_id like nvl(:P35_BOOKING_M_ID, ''%'')    )',
'-----------------------------------------------------',
'------------------Column Data----------------------',
'LOOP',
'htp.p (''<tr>',
' <td style="text-align:center">''||htf.escape_sc(pool.booking_m_id)||''</td>',
' <td style="text-align:left">''||htf.escape_sc(pool.Event_Name)||''</td>',
' <td style="text-align:right">''||htf.escape_sc(to_char(pool.Total_amount,''fm99,99,99,999.00''))||''</td>',
' <td style="text-align:right">''||htf.escape_sc(to_char(pool.Advance,''fm99,99,99,999.00''))||''</td>',
'  <td style="text-align:right">''||htf.escape_sc(to_char(pool.due,''fm99,99,99,999.00''))||''</td>',
'            <td style="text-align:right">''||htf.escape_sc(to_char(pool.last_receive_amount,''fm99,99,99,999.00''))||''</td>',
'   <td style="text-align:right">''||htf.escape_sc(to_char(pool.Total_receive,''fm99,99,99,999.00''))||''</td>',
'    <td style="text-align:right">''||htf.escape_sc(to_char(pool.payable_bill,''fm99,99,99,999.00''))||''</td>',
'     <td style="text-align:right">''||htf.escape_sc(to_char(pool.Bill_Paid,''fm99,99,99,999.00''))||''</td>',
'          <td style="text-align:Center">''||htf.escape_sc(pool.Payment_status)||''</td>',
'<tr>'') ;',
'end LOOP ;',
'htp.p(''</table></center>'') ;',
'END ;',
''))
,p_plug_source_type=>'NATIVE_PLSQL'
);
