,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Declare ',
' v_bk_due             number ; ',
' v_receive            number ; ',
'begin',
' select    due ',
' into      v_bk_due',
' from      booking_m ',
' where     booking_m_id = :P50_BOOKING_M_ID ; ',
'',
'select     nvl(sum(amount), 0)',
'into       v_receive',
'from       receive ',
'where      booking_m_id = :P50_BOOKING_M_ID ; ',
'',
':P50_PAYABLE_AMOUNT := (v_bk_due - v_receive)  ; ',
'',
'end ; ',
' ',
'',
' ',
''))
