begin
wwv_flow_imp_page.create_page(
 p_id=>54
,p_name=>'Client wise Receivable Bill  Details'
,p_alias=>'CLIENT-WISE-RECEIVABLE-BILL-DETAILS'
,p_step_title=>'Client wise Receivable Bill  Details'
,p_autocomplete_on_off=>'OFF'
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'03'
,p_last_updated_by=>'AD_EMS'
,p_last_upd_yyyymmddhh24miss=>'20240503115851'
);
wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(2979448895684975)
,p_name=>'Client wise Receivable Bill  Details'
,p_template=>wwv_flow_imp.id(86612000967782608514)
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select   client.Client_id, client.Client_name, cell_number, ',
'         (select    count(booking_m_id)',
'          from      booking_m',
'          where     client_id = client.client_id) ',
'          number_of_booking,',
'',
'          (select    count(booking_m_id)',
'          from      booking_m ',
'          where     to_char(EVENT_END_DATE, ''MM/DD/YYYY'') <= to_char(sysdate,  ''MM/DD/YYYY'') ',
'          and       client_id = client.client_id ',
'          group by  client_id ) Finished_Events,',
'',
'',
'          (nvl((select   nvl(sum(due), 0) ',
'          from     booking_m bm, client cl ',
'          where    bm.client_id = cl.client_id',
'          and      cl.client_id = CLIENT.client_id ',
'          group by client_name ), 0)) Booking_due, ',
'          ',
'',
'          (nvl((select  sum(AMOUNT)',
'          from     receive re, booking_m bm , client cl',
'          where    re.booking_m_id = bm.booking_m_id',
'          and      bm.client_id = cl.client_id',
'          and      bm.client_id = client.client_id',
'          group by client_name ), 0))  Installment_Receive, ',
'',
'',
'          (nvl((select   nvl(sum(due), 0) ',
'          from     booking_m bm, client cl ',
'          where    bm.client_id = cl.client_id',
'          and      cl.client_id = CLIENT.client_id ',
'          group by client_name ), 0)) - ',
'          ',
'          (nvl((select  sum(AMOUNT)',
'          from     receive re, booking_m bm , client cl',
'          where    re.booking_m_id = bm.booking_m_id',
'          and      bm.client_id = cl.client_id',
'          and      bm.client_id = client.client_id',
'          group by client_name ), 0))  Receiveable_Bill',
'',
'from     CLIENT ',
'where    client_id in (select   client_id ',
'                           from     booking_m) ',
'and      client_id not in (select    client_id',
'                           from      bill b , booking_m bm ',
'                           where     b.booking_m_id  = bm.booking_m_id ) ',
'order by  client.client_id                           ;  ',
'',
''))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(86612027746488608553)
